package ai.openbot.core

import kotlinx.serialization.json.*
import kotlin.test.*

class TypeScriptParityTest {
    // Expected outputs were generated by executing the unchanged original TypeScript sources.
    private val fixture = Json.parseToJsonElement(javaClass.getResource("/typescript-parity.json")!!.readText()).jsonObject

    @Test fun `subagent identifiers are byte-identical to original TypeScript`() {
        fixture["threads"]!!.jsonArray.forEach { row ->
            val item = row.jsonObject
            assertEquals(
                item["expected"]!!.jsonPrimitive.content,
                subagentThreadId(item["parent"]!!.jsonPrimitive.content, item["call"]!!.jsonPrimitive.content),
            )
        }
    }

    @Test fun `approval outcome text is identical to original TypeScript`() {
        fixture["outcomes"]!!.jsonArray.forEach { row ->
            val item = row.jsonObject
            assertEquals(item["expected"]!!.jsonPrimitive.content, outcomeForPerson(item["input"]!!.jsonPrimitive.content))
        }
        assertTrue(doneByPerson(" $HANDLED_BY_PERSON "))
        assertTrue(declinedByPerson(" $DECLINED_BY_PERSON "))
        assertFalse(doneByPerson(DECLINED_BY_PERSON))
    }

    @Test fun `subagent parser accepts wrapped results and rejects malformed shapes`() {
        val wrapped = Json.encodeToString(JsonPrimitive("""{"answer":"Healthy.","threadId":"t","steps":2}"""))
        assertEquals("Healthy.", readSubagentResult(wrapped)!!["answer"]!!.jsonPrimitive.content)
        assertNotNull(readSubagentResult("""{"handedBack":{"tool":"mail/send","reason":"Approval needed","args":{}},"next":"Ask the person","threadId":"t","steps":1}"""))
        listOf(
            "Refused",
            "[]",
            "null",
            """{"answer":"ok","threadId":"t","steps":"2"}""",
            """{"handedBack":{"reason":"missing tool"},"next":"Ask","threadId":"t","steps":1}""",
        ).forEach { assertNull(readSubagentResult(it)) }
    }
}
